478	// failPlanBusiness 是计划类命令共用的业务拒绝输出（退出码 1）。
479	func failPlanBusiness(opts options, stdout, stderr io.Writer, err error, extra map[string]any) int {
480		resp := map[string]any{"accepted": false, "error": err.Error()}
481		for k, v := range extra {
482			resp[k] = v
483		}
484		return failBusiness(opts, stdout, stderr, err, resp)
485	}
486	
487	func cmdPlan(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
488		fs := newFlagSet("plan", &opts)
489		instrument := fs.String("instrument", "", "器具编号")
490		number := fs.String("number", "", "计划编号（全台账唯一，不可复用）")
491		date := fs.String("date", "", "计划日期 YYYY-MM-DD（不早于今天）")
492		note := fs.String("note", "", "非空计划说明")
