556	func cmdCancel(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
557		fs := newFlagSet("cancel", &opts)
558		number := fs.String("number", "", "计划编号")
559		reason := fs.String("reason", "", "非空取消原因")
