572			}
573			return failIO(stderr, err)
574		}
575		human := fmt.Sprintf("计划 %s 已于 %s 取消，原因：%s；不再列入待办。\n",
576			p.Number, p.CanceledAt, p.CancelReason)
577		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
