579	
580	func cmdComplete(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
581		fs := newFlagSet("complete", &opts)
582		number := fs.String("number", "", "计划编号")
583		certificate := fs.String("certificate", "", "证书编号")
584		if err := fs.Parse(args); err != nil {
