595				return failPlanBusiness(opts, stdout, stderr, err, nil)
596			}
597			return failIO(stderr, err)
598		}
599		note := "已完成"
600		if idempotent {
601			note = "该计划已由此证书完成，返回原结果，未刷新完成时间"
602		}
603		human := fmt.Sprintf("%s：计划 %s，证书 %s，完成时间 %s。\n",
604			note, p.Number, p.CertificateNumber, p.CompletedAt)
605		return emit(opts, stdout, stderr, human,
606			map[string]any{"accepted": true, "idempotent": idempotent, "plan": p})
607	}
608	
609	func cmdTodos(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
610		fs := newFlagSet("todos", &opts)
611		instrument := fs.String("instrument", "", "只看该器具编号的待办")
612		if err := fs.Parse(args); err != nil {
613			fmt.Fprintln(stderr, "todos 参数错误：", err)
614			return 2
615		}
616		items, err := l.Todos(*instrument)
617		if err != nil {
618			if errors.Is(err, calibrate.ErrNotFound) {
619				return failBusiness(opts, stdout, stderr, err,
620					map[string]any{"found": false, "error": err.Error()})
621			}
622			return failIO(stderr, err)
623		}
624		var sb strings.Builder
625		if len(items) == 0 {
626			sb.WriteString("无待办。\n")
627		}
628		for _, it := range items {
629			fmt.Fprintf(&sb, "%s\t%s（%s，%s）\t%s\t%s\t%s\n",
630				it.PlanNumber, it.InstrumentID, it.InstrumentName, it.Status,
631				it.PlannedDate, it.Marker, it.Note)
632		}
