		fileSet = true
	case strings.HasPrefix(a, "-f") && len(a) > 2:
		opts.file = a[2:]
		fileSet = true
	case a == "--json":
		opts.asJSON = true
	default:
		if cmd == "" {
			fmt.Fprintf(stderr, "未知全局参数 %s\n\n%s", a, usageText)
			return 2
		}
